// ============================================================
// LinearIndex op_host: Tiling计算 + kernel启动
// ============================================================

#include "torch_kernel_helper.h"
#include "aclrtlaunch_linear_index.h"
#include "tiling/platform/platform_ascendc.h"

#include <torch/extension.h>

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t UB_ALIGN_BYTES = 32;

at::Tensor linear_index(
    const at::Tensor& indices,
    const at::Tensor& shape_tensor,
    int64_t axis,
    int64_t combine) {

    // ---- 输入校验 ----
    TORCH_CHECK(indices.device().type() == c10::DeviceType::PrivateUse1,
                "linear_index: indices must be on NPU device");
    TORCH_CHECK(shape_tensor.device().type() == c10::DeviceType::PrivateUse1,
                "linear_index: shape_tensor must be on NPU device");
    TORCH_CHECK(indices.scalar_type() == at::kInt || indices.scalar_type() == at::kLong,
                "linear_index: indices must be int32 or int64");
    TORCH_CHECK(shape_tensor.scalar_type() == at::kInt,
                "linear_index: shape_tensor must be int32");
    TORCH_CHECK(shape_tensor.dim() == 1,
                "linear_index: shape_tensor must be 1D");

    // ---- 连续化 ----
    auto indicesContig = indices.contiguous();
    int64_t dtypeSize = indicesContig.element_size();  // 4 for int32, 8 for int64
    int64_t totalLength = indicesContig.numel();

    // ---- 读取 shape_tensor 到 host ----
    auto shapeCpu = shape_tensor.cpu();
    auto shapeAcc = shapeCpu.accessor<int32_t, 1>();
    int64_t rank = shapeCpu.size(0);

    // 规范化 axis
    int64_t normAxis = axis;
    if (normAxis < 0) normAxis += rank;
    if (normAxis < 0 || normAxis >= rank) normAxis = rank - 1;

    int64_t targetDim = static_cast<int64_t>(shapeAcc[normAxis]);
    int64_t stride = 0;
    int64_t cols = 0;
    int64_t rows = 0;
    int64_t combineFlag = combine;

    if (rank >= 2) {
        stride = static_cast<int64_t>(shapeAcc[1]);
    }

    // 计算 cols/rows 用于 combine
    if (combineFlag == 1 && rank == 3 && indicesContig.dim() >= 2) {
        cols = indicesContig.size(indicesContig.dim() - 1);
        rows = totalLength / cols;
    }

    // ---- 平台信息 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize = 0;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // ---- Block 级 Tiling ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t alignElementsCache = CACHE_LINE_BYTE_LENGTH / dtypeSize;
    int64_t totalLengthCoreAlign = ((totalLengthCore + alignElementsCache - 1) / alignElementsCache) * alignElementsCache;
    if (totalLengthCoreAlign < alignElementsCache) totalLengthCoreAlign = alignElementsCache;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (usedCoreNum < 1) usedCoreNum = 1;
    if (usedCoreNum > coreNum) usedCoreNum = coreNum;

    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailNum = 1;
    int64_t tailLength = totalLength - (usedCoreNum - 1) * formerLength;
    if (tailLength < 0) tailLength = 0;

    // ---- UB 级 Tiling ----
    // bufferCoefficient: int32=24, int64=40 (基于 UB 分配表)
    int64_t bufferCoefficient = (dtypeSize == 8) ? 40 : 24;
    int64_t maxTileElements = static_cast<int64_t>(ubSize) / bufferCoefficient;
    int64_t alignElementsUb = UB_ALIGN_BYTES / dtypeSize;
    if (alignElementsUb < 1) alignElementsUb = 1;
    int64_t tileLength = (maxTileElements / alignElementsUb) * alignElementsUb;
    if (tileLength < alignElementsUb) tileLength = alignElementsUb;

    // ---- 创建输出 ----
    auto output = at::empty(indicesContig.sizes(),
                            indicesContig.options().dtype(at::kInt));

    // ---- Kernel Launch ----
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    int64_t inputDtypeSize = dtypeSize;

    EXEC_KERNEL_CMD(linear_index, blockDim,
                    indicesContig, output,
                    totalLength, formerNum, formerLength,
                    tailNum, tailLength, tileLength,
                    targetDim, normAxis, combineFlag,
                    rank, stride, cols, rows,
                    inputDtypeSize);

    return output;
}

}  // namespace ascend_kernel
