// ============================================================
// LinearIndex op_kernel: 负数索引修正 + combine 组合计算
// 输入: indices (int32/int64), 输出: int32
// 计算: indices<0 → indices+targetDim, combine时做stride计算
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

// =========================== Int32 Kernel ============================

class KernelLinearIndexInt32 {
public:
    __aicore__ inline KernelLinearIndexInt32() {}

    __aicore__ inline void Init(GM_ADDR indices, GM_ADDR output,
                                 int64_t totalLength, int64_t formerNum, int64_t formerLength,
                                 int64_t tailNum, int64_t tailLength, int64_t tileLength,
                                 int64_t targetDim, int64_t axis, int64_t combineFlag,
                                 int64_t rank, int64_t stride, int64_t cols, int64_t rows);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t tileIdx, int64_t curTileLength);
    __aicore__ inline void Compute(int64_t tileIdx, int64_t curTileLength);
    __aicore__ inline void CopyOut(int64_t tileIdx, int64_t curTileLength);

    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueue;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;
    TBuf<TPosition::VECCALC> tempBuf;
    TBuf<TPosition::VECCALC> maskBuf;

    GlobalTensor<int32_t> indicesGm_;
    GlobalTensor<int32_t> outputGm_;

    int64_t totalLength_ = 0;
    int64_t formerNum_ = 0;
    int64_t formerLength_ = 0;
    int64_t tailNum_ = 0;
    int64_t tailLength_ = 0;
    int64_t tileLength_ = 0;
    int64_t targetDim_ = 0;
    int64_t axis_ = 0;
    int64_t combineFlag_ = 0;
    int64_t rank_ = 0;
    int64_t stride_ = 0;
    int64_t cols_ = 0;
    int64_t rows_ = 0;
};

__aicore__ inline void KernelLinearIndexInt32::Init(
    GM_ADDR indices, GM_ADDR output,
    int64_t totalLength, int64_t formerNum, int64_t formerLength,
    int64_t tailNum, int64_t tailLength, int64_t tileLength,
    int64_t targetDim, int64_t axis, int64_t combineFlag,
    int64_t rank, int64_t stride, int64_t cols, int64_t rows) {

    totalLength_ = totalLength;
    formerNum_ = formerNum;
    formerLength_ = formerLength;
    tailNum_ = tailNum;
    tailLength_ = tailLength;
    tileLength_ = tileLength;
    targetDim_ = targetDim;
    axis_ = axis;
    combineFlag_ = combineFlag;
    rank_ = rank;
    stride_ = stride;
    cols_ = cols;
    rows_ = rows;

    indicesGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(indices), totalLength_);
    outputGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(output), totalLength_);

    int64_t inBufSize = tileLength_ * sizeof(int32_t);
    int64_t outBufSize = tileLength_ * sizeof(int32_t);
    int64_t tempBufSize = tileLength_ * sizeof(int32_t);
    int64_t maskBufSize = (tileLength_ + 31) / 32 * 32;

    pipe.InitBuffer(inQueue, BUFFER_NUM, inBufSize);
    pipe.InitBuffer(outQueue, BUFFER_NUM, outBufSize);
    pipe.InitBuffer(tempBuf, tempBufSize);
    pipe.InitBuffer(maskBuf, maskBufSize);
}

__aicore__ inline void KernelLinearIndexInt32::CopyIn(int64_t tileIdx, int64_t curTileLength) {
    LocalTensor<int32_t> xLocal = inQueue.AllocTensor<int32_t>();
    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(int32_t));
    copyParams.srcStride = 0;
    copyParams.dstStride = 0;
    DataCopyPadExtParams<int32_t> padParams;
    padParams.isPad = false;
    DataCopyPad(xLocal, indicesGm_[tileIdx * tileLength_], copyParams, padParams);
    inQueue.EnQue(xLocal);
}

__aicore__ inline void KernelLinearIndexInt32::Compute(int64_t tileIdx, int64_t curTileLength) {
    LocalTensor<int32_t> xLocal = inQueue.DeQue<int32_t>();
    LocalTensor<int32_t> yLocal = outQueue.AllocTensor<int32_t>();

    // ===== Phase 1: SIMD 向量化负数索引修正 =====
    // Step 1: mask = xLocal < 0
    LocalTensor<uint8_t> maskLocal = maskBuf.Get<uint8_t>();
    LocalTensor<int32_t> zeroLocal = tempBuf.Get<int32_t>();
    AscendC::Duplicate(zeroLocal, static_cast<int32_t>(0), curTileLength);
    AscendC::Compare(maskLocal, xLocal, zeroLocal, AscendC::CMPMODE::LT, curTileLength);
    PipeBarrier<PIPE_ALL>();

    // Step 2: corrected = xLocal + targetDim (复用 tempBuf 覆盖 zero)
    LocalTensor<int32_t> correctedLocal = tempBuf.Get<int32_t>();
    AscendC::Adds(correctedLocal, xLocal, static_cast<int32_t>(targetDim_), curTileLength);
    PipeBarrier<PIPE_ALL>();

    // Step 3: result = mask ? corrected : xLocal
    AscendC::Select(yLocal, maskLocal, correctedLocal, xLocal,
                    AscendC::SELMODE::VSEL_TENSOR_TENSOR_MODE, curTileLength);
    PipeBarrier<PIPE_ALL>();

    // ===== Phase 2: Combine (conditional, scalar path) =====
    if (combineFlag_ == 1 && rank_ == 3 && cols_ > 0) {
        int64_t tileStartFlat = static_cast<int64_t>(tileIdx) * tileLength_;
        for (int64_t i = 0; i < curTileLength; i++) {
            int64_t flatIdx = tileStartFlat + i;
            int32_t val = yLocal.GetValue(i);
            int64_t val64 = static_cast<int64_t>(val);
            if (axis_ == 0) {
                int64_t col = flatIdx % cols_;
                val64 = val64 * stride_ + col;
            } else if (axis_ == 1) {
                int64_t row = flatIdx / cols_;
                val64 = val64 + stride_ * row;
            }
            yLocal.SetValue(i, static_cast<int32_t>(val64));
        }
    }

    outQueue.EnQue<int32_t>(yLocal);
    inQueue.FreeTensor(xLocal);
}

__aicore__ inline void KernelLinearIndexInt32::CopyOut(int64_t tileIdx, int64_t curTileLength) {
    LocalTensor<int32_t> yLocal = outQueue.DeQue<int32_t>();
    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(int32_t));
    copyParams.srcStride = 0;
    copyParams.dstStride = 0;
    DataCopyPad(outputGm_[tileIdx * tileLength_], yLocal, copyParams);
    outQueue.FreeTensor(yLocal);
}

__aicore__ inline void KernelLinearIndexInt32::Process() {
    int64_t blockIdx = GetBlockIdx();
    int64_t coreLength = (blockIdx == formerNum_) ? tailLength_ : formerLength_;
    int64_t coreOffset = blockIdx * formerLength_;

    int64_t tileNum = (coreLength + tileLength_ - 1) / tileLength_;
    int64_t tailTileLength = coreLength - (tileNum - 1) * tileLength_;

    for (int64_t i = 0; i < tileNum - 1; ++i) {
        int64_t tileIdx = (coreOffset + i * tileLength_) / tileLength_;
        CopyIn(tileIdx, tileLength_);
        Compute(tileIdx, tileLength_);
        CopyOut(tileIdx, tileLength_);
    }
    {
        int64_t tileIdx = (coreOffset + (tileNum - 1) * tileLength_) / tileLength_;
        CopyIn(tileIdx, tailTileLength);
        Compute(tileIdx, tailTileLength);
        CopyOut(tileIdx, tailTileLength);
    }
}

// =========================== Int64 Kernel ============================

class KernelLinearIndexInt64 {
public:
    __aicore__ inline KernelLinearIndexInt64() {}

    __aicore__ inline void Init(GM_ADDR indices, GM_ADDR output,
                                 int64_t totalLength, int64_t formerNum, int64_t formerLength,
                                 int64_t tailNum, int64_t tailLength, int64_t tileLength,
                                 int64_t targetDim, int64_t axis, int64_t combineFlag,
                                 int64_t rank, int64_t stride, int64_t cols, int64_t rows);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t tileIdx, int64_t curTileLength);
    __aicore__ inline void Compute(int64_t tileIdx, int64_t curTileLength);
    __aicore__ inline void CopyOut(int64_t tileIdx, int64_t curTileLength);

    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueue;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;

