__aicore__ inline void KernelLinearIndexInt64::Compute(int64_t tileIdx, int64_t curTileLength) {
    LocalTensor<int64_t> xLocal = inQueue.DeQue<int64_t>();
    LocalTensor<int32_t> yLocal = outQueue.AllocTensor<int32_t>();

    // ===== 标量路径: Phase 1 (负数修正) + Phase 2 (combine) + Cast int32 =====
    for (int64_t i = 0; i < curTileLength; i++) {
        int64_t val = xLocal.GetValue(i);
        if (val < 0) {
            val += targetDim_;
