89	__aicore__ inline void KernelLinearIndexInt32::CopyIn(int64_t elemOffset, int64_t curTileLength) {
90	    LocalTensor<int32_t> xLocal = inQueue.AllocTensor<int32_t>();
91	    DataCopyExtParams copyParams;
92	    copyParams.blockCount = 1;
93	    copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(int32_t));
94	    copyParams.srcStride = 0;
95	    copyParams.dstStride = 0;
96	    DataCopyPadExtParams<int32_t> padParams;
97	    padParams.isPad = false;
98	    DataCopyPad(xLocal, indicesGm_[elemOffset], copyParams, padParams);
99	    inQueue.EnQue(xLocal);
