102	__aicore__ inline void KernelLinearIndexInt32::Compute(int64_t elemOffset, int64_t curTileLength) {
103	    LocalTensor<int32_t> xLocal = inQueue.DeQue<int32_t>();
104	    LocalTensor<int32_t> yLocal = outQueue.AllocTensor<int32_t>();
105	
106	    // Phase 1: 负数索引修正 + Phase 2: Combine (if needed)
107	    // 标量路径: 逐元素处理，避免 int32 SIMD 指令兼容性问题
108	    int64_t tileStartFlat = static_cast<int64_t>(tileIdx) * tileLength_;
109	
110	    for (int64_t i = 0; i < curTileLength; i++) {
111	        int64_t val = static_cast<int64_t>(xLocal.GetValue(i));
112	        // Phase 1: negative correction
113	        if (val < 0) {
114	            val += targetDim_;
115	        }
116	        yLocal.SetValue(i, static_cast<int32_t>(val));
117	    }
118	
119	    // Phase 2: Combine (conditional)
120	    if (combineFlag_ == 1 && rank_ == 3 && cols_ > 0) {
121	        for (int64_t i = 0; i < curTileLength; i++) {
122	            int64_t flatIdx = tileStartFlat + i;
123	            int64_t val = static_cast<int64_t>(yLocal.GetValue(i));
124	            if (axis_ == 0) {
125	                int64_t col = flatIdx % cols_;
126	                val = val * stride_ + col;
127	            } else if (axis_ == 1) {
128	                int64_t row = flatIdx / cols_;
129	                val = val + stride_ * row;
130	            }
131	            yLocal.SetValue(i, static_cast<int32_t>(val));
132	        }
133	    }
134	
135	    outQueue.EnQue<int32_t>(yLocal);
136	    inQueue.FreeTensor(xLocal);
137	}
