139	__aicore__ inline void KernelLinearIndexInt32::CopyOut(int64_t elemOffset, int64_t curTileLength) {
140	    LocalTensor<int32_t> yLocal = outQueue.DeQue<int32_t>();
141	    DataCopyExtParams copyParams;
142	    copyParams.blockCount = 1;
143	    copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(int32_t));
144	    copyParams.srcStride = 0;
145	    copyParams.dstStride = 0;
146	    DataCopyPad(outputGm_[tileIdx * tileLength_], yLocal, copyParams);
147	    outQueue.FreeTensor(yLocal);
148	}
