150	__aicore__ inline void KernelLinearIndexInt32::Process() {
151	    int64_t blockIdx = GetBlockIdx();
152	    int64_t coreLength = (blockIdx == formerNum_) ? tailLength_ : formerLength_;
153	    int64_t coreOffset = blockIdx * formerLength_;
154	
155	    int64_t tileNum = (coreLength + tileLength_ - 1) / tileLength_;
156	    int64_t tailTileLength = coreLength - (tileNum - 1) * tileLength_;
157	
158	    for (int64_t i = 0; i < tileNum - 1; ++i) {
159	        int64_t elemOffset = coreOffset + i * tileLength_;
160	        CopyIn(elemOffset, tileLength_);
161	        Compute(elemOffset, tileLength_);
162	        CopyOut(elemOffset, tileLength_);
163	    }
164	    {
165	        int64_t elemOffset = coreOffset + (tileNum - 1) * tileLength_;
166	        CopyIn(elemOffset, tailTileLength);
167	        Compute(elemOffset, tailTileLength);
168	        CopyOut(elemOffset, tailTileLength);
169	    }
170	}
