302	__aicore__ inline void KernelLinearIndexInt64::Process() {
303	    int64_t blockIdx = GetBlockIdx();
304	    int64_t coreLength = (blockIdx == formerNum_) ? tailLength_ : formerLength_;
305	    int64_t coreOffset = blockIdx * formerLength_;
306	
307	    int64_t tileNum = (coreLength + tileLength_ - 1) / tileLength_;
308	    int64_t tailTileLength = coreLength - (tileNum - 1) * tileLength_;
309	
310	    for (int64_t i = 0; i < tileNum - 1; ++i) {
311	        int64_t elemOffset = coreOffset + i * tileLength_;
312	        CopyIn(elemOffset, tileLength_);
313	        Compute(elemOffset, tileLength_);
314	        CopyOut(elemOffset, tileLength_);
315	    }
316	    {
317	        int64_t elemOffset = coreOffset + (tileNum - 1) * tileLength_;
318	        CopyIn(tileIdx, tailTileLength);
319	        Compute(elemOffset, tailTileLength);
320	        CopyOut(elemOffset, tailTileLength);
321	    }
322	}
